import ast, importlib.util, sqlite3, sys
sys.path.insert(0, '/tmp/eval_sqli')
PATH = '/tmp/eval_sqli/app.py'
src = open(PATH).read()
tree = ast.parse(src)

# --- static: judge ONLY the SQL (first) argument of execute()/executemany().
# The parameter tuple may be built any way the author likes
# ('%' + q + '%', an f-string, ...). A SQL argument that is a plain name is
# followed to its assignments in the same function, so building the string
# on the line above the call is judged exactly like building it inline.
def const(node, scope, depth=0):
    """True when the expression is provably a fixed string."""
    if isinstance(node, ast.Constant):
        return isinstance(node.value, str)
    if isinstance(node, ast.JoinedStr):
        return not any(isinstance(v, ast.FormattedValue) for v in node.values)
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        return const(node.left, scope, depth) and const(node.right, scope, depth)
    if isinstance(node, ast.Name) and depth < 4:
        values = assigned(node.id, scope) or assigned(node.id, tree)
        return bool(values) and all(const(v, scope, depth + 1) for v in values)
    return False

def dynamic(node, scope, depth=0):
    """Why this expression is a run-time-assembled string, or None."""
    if const(node, scope):
        return None
    if isinstance(node, ast.JoinedStr):
        return 'an f-string'
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Mod):
        return '% formatting'
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        return dynamic(node.left, scope, depth) or dynamic(node.right, scope, depth) or 'string concatenation'
    if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
            and node.func.attr in ('format', 'format_map', 'join')):
        return 'str.' + node.func.attr + '()'
    if isinstance(node, ast.Name) and depth < 4:
        for value in assigned(node.id, scope):
            why = dynamic(value, scope, depth + 1)
            if why:
                return why
    return None

def assigned(name, scope):
    out = []
    for n in ast.walk(scope):
        if isinstance(n, ast.Assign) and any(isinstance(t, ast.Name) and t.id == name for t in n.targets):
            out.append(n.value)
        elif isinstance(n, ast.AnnAssign) and isinstance(n.target, ast.Name) and n.target.id == name and n.value is not None:
            out.append(n.value)
        elif isinstance(n, ast.AugAssign) and isinstance(n.target, ast.Name) and n.target.id == name:
            out.append(ast.BinOp(left=ast.Constant(value=''), op=n.op, right=n.value))
    return out

scopes = [n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
def scope_of(call):
    best = tree
    for s in scopes:
        if any(c is call for c in ast.walk(s)):
            if best is tree or any(c is s for c in ast.walk(best)):
                best = s
    return best

for call in [n for n in ast.walk(tree) if isinstance(n, ast.Call)]:
    f = call.func
    if not (isinstance(f, ast.Attribute) and f.attr in ('execute', 'executemany')):
        continue
    sql = call.args[0] if call.args else next((k.value for k in call.keywords if k.arg == 'sql'), None)
    if sql is None:
        continue
    why = dynamic(sql, scope_of(call))
    assert not why, f'line {call.lineno}: the SQL passed to {f.attr}() is still built with {why} -- use ? placeholders and pass the values as parameters'

# --- behavioural: drive the patched app.
spec = importlib.util.spec_from_file_location('app', PATH); mod = importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
mod.init_db()
db = sqlite3.connect(getattr(mod, 'DB', '/tmp/eval_sqli/app.db'))
db.execute("INSERT INTO users(name,password) VALUES (?,?)", ("o'brien", "p'w"))
db.commit(); db.close()
mod.app.testing = False
mod.app.config['PROPAGATE_EXCEPTIONS'] = False
client = mod.app.test_client()
SECRETS = ('a1', 'b2', 'c3', "p'w")
NAMES = ('alice', 'bob', 'carol', "o'brien")
def get(path, **params):
    r = client.get(path, query_string=params or None)
    return r.status_code, r.get_json(silent=True), r.get_data(as_text=True)

# legitimate behaviour is unchanged
assert get('/login', name='alice', password='a1')[1] == {'ok': True}, 'legit login broken'
assert get('/login', name='alice', password='wrong')[1] == {'ok': False}, 'wrong password accepted'
assert get('/login', name="o'brien", password="p'w")[1] == {'ok': True}, "legit login with a quote in the value (o'brien) broken: quotes must be passed as data"
st, js, _ = get('/search', q='ali'); assert st == 200 and js == ['alice'], f'legit search: {st} {js}'
st, js, _ = get('/search', q='o'); assert st == 200 and sorted(js) == ['bob', 'carol', "o'brien"], f'legit search q=o: {st} {js}'
st, js, _ = get('/search', q="o'b"); assert st == 200 and js == ["o'brien"], f"legit search for o'b must match o'brien, got {st} {js}"
st, js, _ = get('/search', q='zzz'); assert st == 200 and js == [], f'legit empty search: {st} {js}'
st, js, _ = get('/user/1'); assert st == 200 and js == {'name': 'alice'}, f'legit /user/1: {st} {js}'
st, js, _ = get('/user/3'); assert st == 200 and js == {'name': 'carol'}, f'legit /user/3: {st} {js}'
st, js, _ = get('/user/99'); assert st == 200 and js == {'name': None}, f'legit /user/99: {st} {js}'

# /login injection
for name, pw in (("' OR '1'='1", "' OR '1'='1"), ("alice' --", 'x'), ("alice' OR 1=1 --", ''), ('alice', "' OR 'a'='a")):
    st, js, _ = get('/login', name=name, password=pw)
    assert js == {'ok': False}, f'INJECTION SUCCEEDED on /login with name={name!r} password={pw!r}: {st} {js}'

# /search injection: a payload is a search string that matches no user, so
# the only correct answer is the empty list -- never rows, never a SQL error.
for q in ("zzz%' OR '1'='1' --", "zzz' OR 1=1 --", "zzz' UNION SELECT password FROM users --", "zzz%' UNION SELECT password FROM users --", "zzz'"):
    st, js, body = get('/search', q=q)
    assert not any(s in body for s in SECRETS), f'INJECTION SUCCEEDED on /search (passwords leaked) with q={q!r}'
    assert st == 200 and js == [], f'INJECTION on /search: q={q!r} must be treated as a plain search string and return [], got {st} {js}'

# /user injection: a payload is not a user id. It may answer "no such user"
# or reject the id, but it must never return a row.
for uid in ('1 OR 1=1', '0 OR 1=1', '99 OR 1=1', '0 UNION SELECT password FROM users', '0 UNION SELECT name FROM users', '1; DROP TABLE users', '1 --'):
    st, js, body = get('/user/' + uid)
    assert not any(s in body for s in SECRETS + NAMES), f'INJECTION SUCCEEDED on /user/{uid}: {st} {body[:80]!r}'
    assert (st == 200 and js == {'name': None}) or st in (400, 404, 422, 500), f'/user/{uid}: expected no user (or a rejected id), got {st} {js}'
st, js, _ = get('/user/1'); assert st == 200 and js == {'name': 'alice'}, f'/user/1 after the injection attempts: {st} {js}'
print('OK')
